import React from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Divider,
  Grid,
  Link,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import {
  EmojiEvents as AwardIcon,
  GppGood as PatentIcon,
  Groups as TeamIcon,
  Info as AboutIcon,
  Nature as EcoIcon,
  OpenInNew as OpenInNewIcon,
  Science as ScienceIcon,
} from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import { alpha, useTheme } from '@mui/material/styles';
import { useRegistration } from '../context/RegistrationContext';
import {
  ABOUT_AWARDS,
  ABOUT_HISTORY,
  ABOUT_MISSION,
  ABOUT_TEAM,
  ABOUT_US_PAGE,
  CARBON_INTELLIGENCE_SOLUTION,
  PATENT_PENDING_HIGHLIGHT,
  SUSTAINOW_SOLUTIONS_SUITE,
} from '../constants/aboutUsContent';
import MarketingHeading from './shared/MarketingHeading';

const AboutUsPage: React.FC = () => {
  const theme = useTheme();
  const { isRegistered } = useRegistration();
  const isDark = theme.palette.mode === 'dark';

  return (
    <Box sx={{ maxWidth: 960, mx: 'auto', py: { xs: 2, md: 3 } }}>
      <Stack direction="row" spacing={1.5} alignItems="center" sx={{ mb: 2 }}>
        <Box
          sx={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            width: 48,
            height: 48,
            borderRadius: 2,
            bgcolor: alpha(theme.palette.primary.main, 0.12),
            color: 'primary.main',
          }}
        >
          <AboutIcon />
        </Box>
        <Box>
          <MarketingHeading level="h1">
            {ABOUT_US_PAGE.title}
          </MarketingHeading>
          <Typography variant="subtitle1" color="primary.main" sx={{ fontWeight: 700 }}>
            {ABOUT_US_PAGE.tagline}
          </Typography>
        </Box>
      </Stack>

      <Paper
        variant="outlined"
        sx={{
          p: { xs: 2, md: 2.5 },
          mb: 3,
          borderStyle: 'dashed',
          borderColor: alpha(theme.palette.primary.main, 0.35),
          bgcolor: alpha(theme.palette.primary.main, isDark ? 0.06 : 0.04),
        }}
      >
        <Typography variant="body1" sx={{ fontStyle: 'italic', mb: 1 }}>
          &ldquo;{ABOUT_US_PAGE.quote.text}&rdquo;
        </Typography>
        <Typography variant="caption" color="text.secondary">
          — {ABOUT_US_PAGE.quote.attribution}
        </Typography>
      </Paper>

      <Paper
        elevation={0}
        sx={{
          p: { xs: 2, md: 3 },
          mb: 3,
          borderRadius: 3,
          border: `2px solid ${alpha(theme.palette.primary.main, isDark ? 0.45 : 0.35)}`,
          bgcolor: alpha(theme.palette.primary.main, isDark ? 0.1 : 0.06),
        }}
      >
        <Stack direction="row" spacing={1.5} alignItems="flex-start" sx={{ mb: 2 }}>
          <PatentIcon color="primary" sx={{ mt: 0.25 }} />
          <Box>
            <Typography variant="subtitle1" sx={{ fontWeight: 800, color: 'primary.main', mb: 0.5 }}>
              {PATENT_PENDING_HIGHLIGHT.label}
            </Typography>
            <Typography variant="body2" color="text.secondary">
              {PATENT_PENDING_HIGHLIGHT.description}
            </Typography>
          </Box>
        </Stack>
      </Paper>

      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} md={6}>
          <Card variant="outlined" sx={{ height: '100%' }}>
            <CardContent>
              <MarketingHeading level="h3" gutterBottom>
                {ABOUT_MISSION.title}
              </MarketingHeading>
              {ABOUT_MISSION.paragraphs.map((paragraph) => (
                <Typography key={paragraph.slice(0, 40)} variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
                  {paragraph}
                </Typography>
              ))}
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={6}>
          <Card variant="outlined" sx={{ height: '100%' }}>
            <CardContent>
              <MarketingHeading level="h3" gutterBottom>
                {ABOUT_HISTORY.title}
              </MarketingHeading>
              {ABOUT_HISTORY.paragraphs.map((paragraph) => (
                <Typography key={paragraph.slice(0, 40)} variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
                  {paragraph}
                </Typography>
              ))}
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      <MarketingHeading level="h2" sx={{ mb: 2 }}>
        {ABOUT_AWARDS.title}
      </MarketingHeading>
      <Grid container spacing={2} sx={{ mb: 4 }}>
        {ABOUT_AWARDS.items.map((item) => (
          <Grid item xs={12} md={4} key={item.title}>
            <Card variant="outlined" sx={{ height: '100%' }}>
              <CardContent>
                <Stack direction="row" spacing={1} alignItems="flex-start" sx={{ mb: 1 }}>
                  <AwardIcon color="primary" fontSize="small" sx={{ mt: 0.25 }} />
                  <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
                    {item.title}
                  </Typography>
                </Stack>
                <Typography variant="body2" color="text.secondary">
                  {item.description}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      <Card variant="outlined" sx={{ mb: 4 }}>
        <CardContent>
          <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1.5 }}>
            <TeamIcon color="primary" />
            <MarketingHeading level="h3">
              {ABOUT_TEAM.title}
            </MarketingHeading>
          </Stack>
          {ABOUT_TEAM.paragraphs.map((paragraph) => (
            <Typography key={paragraph.slice(0, 40)} variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
              {paragraph}
            </Typography>
          ))}
        </CardContent>
      </Card>

      <Divider sx={{ mb: 3 }} />

      <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1 }}>
        <EcoIcon color="primary" />
        <MarketingHeading level="h2">
          {CARBON_INTELLIGENCE_SOLUTION.title}
        </MarketingHeading>
      </Stack>
      <Typography variant="body1" color="text.secondary" sx={{ mb: 2 }}>
        {CARBON_INTELLIGENCE_SOLUTION.platformSummary}
      </Typography>
      <Typography variant="body1" sx={{ fontWeight: 600, mb: 2 }}>
        {CARBON_INTELLIGENCE_SOLUTION.lead}
      </Typography>
      {CARBON_INTELLIGENCE_SOLUTION.paragraphs.map((paragraph) => (
        <Typography key={paragraph.slice(0, 40)} variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
          {paragraph}
        </Typography>
      ))}

      <Grid container spacing={2} sx={{ mt: 1, mb: 4 }}>
        {CARBON_INTELLIGENCE_SOLUTION.capabilities.map((cap) => (
          <Grid item xs={12} sm={6} key={cap.title}>
            <Paper variant="outlined" sx={{ p: 2, height: '100%' }}>
              <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 1 }}>
                {cap.title}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {cap.description}
              </Typography>
            </Paper>
          </Grid>
        ))}
      </Grid>

      <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 1 }}>
        <ScienceIcon color="primary" />
        <MarketingHeading level="h2">
          {SUSTAINOW_SOLUTIONS_SUITE.title}
        </MarketingHeading>
      </Stack>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        {SUSTAINOW_SOLUTIONS_SUITE.intro}
      </Typography>
      <Stack spacing={1.5} sx={{ mb: 4 }}>
        {SUSTAINOW_SOLUTIONS_SUITE.items.map((item) => (
          <Paper key={item.title} variant="outlined" sx={{ p: 2 }}>
            <Stack
              direction={{ xs: 'column', sm: 'row' }}
              spacing={0.5}
              alignItems={{ xs: 'flex-start', sm: 'baseline' }}
              justifyContent="space-between"
              sx={{ mb: 0.5 }}
            >
              <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
                {item.title}
              </Typography>
              {item.url ? (
                <Link
                  href={item.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  sx={{
                    fontWeight: 600,
                    fontSize: '0.8125rem',
                    display: 'inline-flex',
                    alignItems: 'center',
                    gap: 0.5,
                  }}
                >
                  {item.urlLabel || item.url}
                  <OpenInNewIcon sx={{ fontSize: 14 }} />
                </Link>
              ) : null}
            </Stack>
            <Typography variant="body2" color="text.secondary">
              {item.description}
            </Typography>
          </Paper>
        ))}
      </Stack>

      <Paper
        variant="outlined"
        sx={{
          p: { xs: 2, md: 3 },
          display: 'flex',
          flexDirection: { xs: 'column', sm: 'row' },
          alignItems: { xs: 'flex-start', sm: 'center' },
          justifyContent: 'space-between',
          gap: 2,
        }}
      >
        <Box>
          <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
            Get in touch
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Questions, partnerships, or demos:{' '}
            <Link href={`mailto:${ABOUT_US_PAGE.contactEmail}`} sx={{ fontWeight: 600 }}>
              {ABOUT_US_PAGE.contactEmail}
            </Link>
          </Typography>
          <Stack direction="row" spacing={1} sx={{ mt: 1, flexWrap: 'wrap' }}>
            <Chip
              size="small"
              label={PATENT_PENDING_HIGHLIGHT.label}
              color="primary"
              variant="outlined"
            />
            <Chip size="small" label="RBIH GreenFinTech Hackathon 2024" variant="outlined" />
          </Stack>
        </Box>
        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
          <Button
            component="a"
            href={ABOUT_US_PAGE.websiteUrl}
            target="_blank"
            rel="noopener noreferrer"
            variant="outlined"
            endIcon={<OpenInNewIcon />}
          >
            {ABOUT_US_PAGE.websiteLabel}
          </Button>
          <Button
            component={RouterLink}
            to={isRegistered ? '/dashboard' : '/register?type=msme'}
            variant="contained"
          >
            {isRegistered ? 'Back to workspace' : 'Register your MSME'}
          </Button>
        </Stack>
      </Paper>
    </Box>
  );
};

export default AboutUsPage;
